import { CommonModule } from '@angular/common';
import { Component, Input, ViewChild } from '@angular/core';
import { MatCardModule } from '@angular/material/card';
import { MatTableDataSource, MatTableModule } from '@angular/material/table';
import { MaterialModule } from 'src/app/material.module';
import { MatIconModule } from '@angular/material/icon';
import { MatMenuModule } from '@angular/material/menu';
import { MatButtonModule } from '@angular/material/button';
import { TableService } from './tableService';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { EditDialogComponent } from './edit-dialog/edit-dialog.component';
import { AddDialogComponent } from './add-dialog/add-dialog.component';
import { DeleteDialogComponent } from './delete-dialog/delete-dialog.component';
import { MatPaginator, MatPaginatorModule } from '@angular/material/paginator';
import { MatSort, MatSortModule } from '@angular/material/sort';
import { StatusDialogComponent } from './status-dialog/status-dialog.component';
// table 1
export interface productsData {
  id: number;
  imagePath: string;
  uname: string;
  budget: number;
  priority: string;
}

const PRODUCT_DATA: productsData[] = [
  {
    id: 1,
    imagePath: 'assets/images/products/product-1.png',
    uname: 'iPhone 13 pro max-Pacific Blue-128GB storage',
    budget: 180,
    priority: 'confirmed',
  },
  {
    id: 2,
    imagePath: 'assets/images/products/product-2.png',
    uname: 'Apple MacBook Pro 13 inch-M1-8/256GB-space',
    budget: 90,
    priority: 'cancelled',
  },
  {
    id: 3,
    imagePath: 'assets/images/products/product-3.png',
    uname: 'PlayStation 5 DualSense Wireless Controller',
    budget: 120,
    priority: 'rejected',
  },
  {
    id: 4,
    imagePath: 'assets/images/products/product-4.png',
    uname: 'Amazon Basics Mesh, Mid-Back, Swivel Office',
    budget: 160,
    priority: 'confirmed',
  },
];

@Component({
  selector: 'app-tables',
  imports: [
    MatTableModule,
    CommonModule,
    MatCardModule,
    MaterialModule,
    MatIconModule,
    MatMenuModule,
    MatButtonModule,
    MatPaginatorModule,
    MatSortModule,
  ],
  templateUrl: './tables.component.html',
})
export class AppTablesComponent {
  displayedColumns: string[] = ['image', 'uname']; // Define table columns
  dataSource1: any[] = []; // Store retrieved user data
  displayedColumns1: string[] = ['index_number','student_name','academic_year', 'phone_number','department','inquiry_type','forwarded_to','updated_status','created_at','remarks' , 'budget'];
  selectedRow: any = null;

  showToast: boolean = false;
  toastMessage: string = '';
  toastType: string = '';  // This will hold the type of the toast (success, error, info)]
  datafiltered: any;
  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;
  @Input() childData: any[] = [];
  constructor(private userService: TableService,
    private tableService: TableService,
    private dialog: MatDialog,
    private snackBar: MatSnackBar  
  ) {}

  selectRow(row: any): void {
    this.selectedRow = row;
  }
  ngOnInit(){
    // alert('tables')
    this.getData();
    // this.dataSource1 = this.childData;
    
  }

    // Method to get the user name by their ID or identifier
    getForwardedUserName(forwardedId: any): string {
      const user = this.forwordedList.find(user => user.id == forwardedId); 
      console.log("user",user)// Assuming 'id' is the key
      return user ? user.email : '-';  // Return user name or 'Unknown' if not found
    }
  getData(){
    this.userService.getInqueries().subscribe({
      next: (data) => {
        console.log("get data : ", data)
        this.dataSource1 = data.inquiries;

        
  this.datafiltered = new MatTableDataSource(this.dataSource1); // Replace ELEMENT_DATA with your actual data array
  this.datafiltered.paginator = this.paginator;
  this.datafiltered.sort = this.sort;
  // this.datafiltered = dataSource2.filterPredicate = (data, filter) => {
  //   return data.student_name.toLowerCase().includes(filter);
  // };
  
      },
      error: (error) => {
        console.error('Error fetching users:', error);
      }
    });
  }
  
  applyFilter(event: Event) {
    console.log("event",event)
    const filterValue = (event.target as HTMLInputElement).value.trim().toLowerCase();
    console.log("filterValue",filterValue)
    this.datafiltered.filter = filterValue;
  }
  
  statusUpdate(element: any){
    console.log(element, "edit records")
    // Open a dialog or form for editing
    const dialogRef = this.dialog.open(StatusDialogComponent, {
      data: element,
      disableClose: true, // Prevent closing when clicking outside
    });
   
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        // Save the changes after closing the dialog
        // this.updateRow(result);
        this.showToastMessage('Status updated successfully','success');
        this.getData(); // Refresh table data
      }
    });
  }

  // Edit row functionality
  editRow(element: any): void {
    console.log(element, "edit records")
    // Open a dialog or form for editing
    const dialogRef = this.dialog.open(EditDialogComponent, {
      data: element,
      width: '500px', // Adjust width
      height: '550px', // Adjust height
      disableClose: true, // Prevent closing when clicking outside
    });
   
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        // Save the changes after closing the dialog
        // this.updateRow(result);
        this.showToastMessage('Record edit successfully','success');
        this.getData(); // Refresh table data
      }
    });
  }

   // Edit row functionality
   deleteRow(element: any): void {
    console.log(element, "edit records")
    // Open a dialog or form for editing
    const dialogRef = this.dialog.open(DeleteDialogComponent, {
      data: element
    });
   
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.showToastMessage('Record delete successfully','error');
        // Save the changes after closing the dialog
        this.getData(); // Refresh table data
      }
    });
  }

  // Update row data
  // updateRow(updatedData: any): void {
  //   this.tableService.updateUser(updatedData).subscribe(
  //     () => {
  //       this.snackBar.open('Record updated successfully', 'Close', { duration: 2000 });
  //       this.getData(); // Refresh table data
  //     },
  //     error => {
  //       this.snackBar.open('Error updating record', 'Close', { duration: 2000 });
  //     }
  //   );
  // }

  // Delete row functionality
  // deleteRow(id: number): void {
  //   if (confirm('Are you sure you want to delete this record?')) {
  //     this.tableService.deleteInquiry(id).subscribe(
  //       () => {
  //         this.snackBar.open('Record deleted successfully', 'Close', { duration: 2000 });
  //         this.getData(); // Refresh table data
  //       },
  //       error => {
  //         this.snackBar.open('Error deleting record', 'Close', { duration: 2000 });
  //       }
  //     );
  //   }
  // }

  // Add new user
  addRow(): void {
    const dialogRef = this.dialog.open(AddDialogComponent, {
      width: '500px', // Adjust width
      height: '550px', // Adjust height
      disableClose: true, // Prevent closing when clicking outside
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.showToastMessage('Record added successfully','success');
        this.getData(); // Refresh table data
      }
    });
  }

  // // Save new row data
  // saveNewRow(newData: any): void {
  //   console.log("add data",newData)
  //   this.tableService.addUser(newData).subscribe(
  //     () => {
  //       this.snackBar.open('Record added successfully', 'Close', { duration: 2000 });
  //       this.getData(); // Refresh table data
  //     },
  //     error => {
  //       this.snackBar.open('Error adding record', 'Close', { duration: 2000 });
  //     }
  //   );
  // }


    
   // Method to show success toast
   showToastMessage(message: string , type: string) {
    this.toastMessage = message;
    this.showToast = true;
    this.toastType = type
    // Hide toast after 3 seconds
    setTimeout(() => {
      this.showToast = false;
      // this.onCancel();
    }, 3000);
  }

   // Method to close toast manually
closeToast() {
  this.showToast = false;
}
}
<mat-card class="cardWithShadow">
  
  
  
 
 <mat-card-content>
  
  <div class="d-flex justify-content-between align-items-center m-b-16">
    <!-- Search Field -->
    <mat-form-field appearance="outline" class="w-25">
      <mat-label>Search</mat-label>
      <input matInput (keyup)="applyFilter($event)" placeholder="Enter Index Number Or Status">
    </mat-form-field>
  
    <!-- Add New Button -->
    <button mat-raised-button color="primary" (click)="addRow()">
      <mat-icon>add</mat-icon> Add New
    </button>
  </div>
   <div class="table-responsive">
     <table mat-table [dataSource]="datafiltered" matSort matPaginator class="w-100">
       
       <ng-container matColumnDef="index_number">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Index Number</th>
         <td mat-cell *matCellDef="let element">{{ element.index_number }}</td>
       </ng-container>

       <ng-container matColumnDef="student_name">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Student Name</th>
         <td mat-cell *matCellDef="let element">{{ element.student_name }}</td>
       </ng-container>
       
       <ng-container matColumnDef="academic_year">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Academic Year</th>
         <td mat-cell *matCellDef="let element">{{ element.academic_year }}</td>
       </ng-container>
       
       <ng-container matColumnDef="phone_number">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Phone Number</th>
         <td mat-cell *matCellDef="let element">{{ element.phone_number }}</td>
       </ng-container>
       
       <ng-container matColumnDef="department">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Department</th>
         <td mat-cell *matCellDef="let element">{{ element.department }}</td>
       </ng-container>
       
       <ng-container matColumnDef="inquiry_type">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Inquiry Type</th>
         <td mat-cell *matCellDef="let element">{{ element.inquiry }}</td>
       </ng-container>
       
       <ng-container matColumnDef="forwarded_to">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Forwarded To</th>
         <td mat-cell *matCellDef="let element">{{ element.forwarded_to }}</td>
       </ng-container>

       <!-- <ng-container matColumnDef="initial_status">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Initial Status</th>
         <td mat-cell *matCellDef="let element">{{ element.initial_status }}</td>
       </ng-container> -->

       <ng-container matColumnDef="updated_status">
        <th mat-header-cell *matHeaderCellDef mat-sort-header>Status</th>
        <td mat-cell *matCellDef="let element" 
            [ngStyle]="{
              'color': element.initial_status_1 === 'Forwarded' ? 'gray' : 
                       element.initial_status_1 === 'Resolved' ? 'green' : 
                       element.initial_status_1 === 'Rejected' ? 'orange' : 'black',
              'font-weight': 'bold'
            }">
          {{ element.initial_status_1 }}
        </td>
      </ng-container>
      

       <ng-container matColumnDef="created_at">
         <th mat-header-cell *matHeaderCellDef mat-sort-header>Last Updated At</th>
         <td mat-cell *matCellDef="let element">{{ element.created_at }}</td>
       </ng-container>
       <ng-container matColumnDef="remarks">
        <th mat-header-cell *matHeaderCellDef mat-sort-header>Remarks</th>
        <td mat-cell *matCellDef="let element">{{ element.remarks }}</td>
      </ng-container>
       <ng-container matColumnDef="budget">
         <th mat-header-cell *matHeaderCellDef>Actions</th>
         <td mat-cell *matCellDef="let element">
           <button mat-icon-button [matMenuTriggerFor]="menu">
             <mat-icon>more_vert</mat-icon>
           </button>
           <mat-menu #menu="matMenu">
            <button mat-menu-item (click)="statusUpdate(element)">
              <mat-icon>update</mat-icon>
              <span>Status Update</span>
            </button>
             <button mat-menu-item (click)="editRow(element)">
               <mat-icon>edit</mat-icon>
               <span>Edit</span>
             </button>
             <button mat-menu-item (click)="deleteRow(element)">
               <mat-icon>delete</mat-icon>
               <span>Delete</span>
             </button>
           </mat-menu>
         </td>
       </ng-container>
       
       <tr mat-header-row *matHeaderRowDef="displayedColumns1"></tr>
       <tr mat-row *matRowDef="let row; columns: displayedColumns1" (click)="selectRow(row)"></tr>
     </table>
     
     <mat-paginator [pageSize]="5" [pageSizeOptions]="[5, 10, 20]" showFirstLastButtons></mat-paginator>
   </div>
 </mat-card-content>
</mat-card>

<!-- Toast Notification -->
<div class="toast-container position-fixed top-0 end-0" [ngClass]="{
  'bg-success': toastType === 'success', 
  'bg-danger': toastType === 'error',
  'bg-warning': toastType === 'warning',
  'bg-info': toastType === 'info'
}"  style="width: 200px;">
 <div *ngIf="showToast" class="toast align-items-center text-white bg-success border-0 show" role="alert" aria-live="assertive" aria-atomic="true">
   <div class="d-flex">
     <div class="toast-body">
       {{ toastMessage }}
     </div>
     <!-- <button type="button" class="btn-close btn-close-white" (click)="closeToast()" aria-label="Close"></button> -->
   </div>
 </div>
</div>
